def f(x, y):
    return (x + y) * (x + y + 1) // 2 + min(x, y)

print("Parity Table (E=Even, O=Odd) for 0 <= x, y < 5:")
print("y\\x | 0 | 1 | 2 | 3 | 4")
for y in range(5):
    row = []
    for x in range(5):
        val = f(x, y)
        parity = 'O' if val % 2 != 0 else 'E'
        row.append(parity)
    print(f"{y}  | {' '.join(row)}")
